import{_ as n}from"./chunks/folders.9ioZn9MV.js";import{_ as i,c as r,o as t,a2 as a}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Ordner vergleichen","description":"Sehen Sie neue, geänderte und fehlende Dateien in zwei Ordnern, filtern Sie den Baum und bringen Sie beide Seiten in Einklang.","frontmatter":{"title":"Ordner vergleichen","description":"Sehen Sie neue, geänderte und fehlende Dateien in zwei Ordnern, filtern Sie den Baum und bringen Sie beide Seiten in Einklang."},"headers":[],"relativePath":"de/guide/folders.md","filePath":"de/guide/folders.md","lastUpdated":1794296122000}'),s={name:"de/guide/folders.md"};function l(d,e,o,u,h,c){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="ordner-vergleichen" tabindex="-1">Ordner vergleichen <a class="header-anchor" href="#ordner-vergleichen" aria-label="Permalink to &quot;Ordner vergleichen&quot;">​</a></h1><p>Wenn zwei Ordner übereinstimmen sollen — eine Arbeitskopie und ihre Sicherung, ein alter Export und ein neuer —, ist der Vergleich Datei für Datei mühsam. qDiff zeigt den gesamten Baum auf einmal.</p><img src="'+n+'" alt="Zwei Ordnerbäume mit farbigen Dateizuständen" class="guide-shot"><h2 id="zwei-ordner-offnen" tabindex="-1">Zwei Ordner öffnen <a class="header-anchor" href="#zwei-ordner-offnen" aria-label="Permalink to &quot;Zwei Ordner öffnen&quot;">​</a></h2><p>Ziehen Sie zwei Ordner ins Fenster oder wählen Sie sie über <strong>Ablage → Öffnen</strong> aus. Auch Ordner innerhalb von Ordnern werden verglichen, sodass Sie das vollständige Bild sehen.</p><h2 id="den-baum-auf-einen-blick-lesen" tabindex="-1">Den Baum auf einen Blick lesen <a class="header-anchor" href="#den-baum-auf-einen-blick-lesen" aria-label="Permalink to &quot;Den Baum auf einen Blick lesen&quot;">​</a></h2><ul><li><strong>Grün</strong> — eine Datei, die nur auf einer Seite existiert.</li><li><strong>Orange</strong> — der Name stimmt überein, der Inhalt weicht ab.</li><li><strong>Rot</strong> — eine Datei, die auf der anderen Seite fehlt.</li><li><strong>Grau</strong> — beide Seiten stimmen überein.</li></ul><h2 id="nur-zeigen-was-zahlt" tabindex="-1">Nur zeigen, was zählt <a class="header-anchor" href="#nur-zeigen-was-zahlt" aria-label="Permalink to &quot;Nur zeigen, was zählt&quot;">​</a></h2><p>Nutzen Sie die Statusfilter, um alles auszublenden, was bereits übereinstimmt, oder tippen Sie einen Teil eines Namens ein, um die Liste einzugrenzen. Sie können eine schnelle Prüfung nur nach Namen wählen oder qDiff auch die Inhalte lesen lassen — nützlich, wenn eine Sicherung richtig aussieht, aber innen vielleicht veraltet ist.</p><p>Auch große Ordner öffnen sich schnell, sodass Sie nicht auf eine Fortschrittsanzeige starren müssen.</p><h2 id="direkt-aus-der-liste-korrigieren" tabindex="-1">Direkt aus der Liste korrigieren <a class="header-anchor" href="#direkt-aus-der-liste-korrigieren" aria-label="Permalink to &quot;Direkt aus der Liste korrigieren&quot;">​</a></h2><p>Kopieren Sie eine Datei auf die andere Seite, entfernen Sie einen Überrest oder synchronisieren Sie eine ganze Gruppe — alles im selben Baum. Sie müssen nicht zum Finder zurückwechseln.</p><div class="tip custom-block"><p class="custom-block-title">Bedenkenlos stöbern</p><p>Auf der Festplatte wird nichts verändert, bis Sie eine Aktion wählen. Das Durchsehen und Filtern eines Vergleichs ist völlig gefahrlos.</p></div><p>Weiter: <a href="./projects.html">ein Projekt vor dem Commit prüfen</a>.</p>',14)])])}const p=i(s,[["render",l]]);export{m as __pageData,p as default};
